 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    # The stamp is the longest contiguous non-background horizontal segment.
    best = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            s = c
            while c < w and row[c] != bg:
                c += 1
            if best is None or c - s > best[0]:
                best = (c - s, r, s, row[s:c][:])
    _, sr, sc, stamp = best
    stamp_colors = set(stamp)
    out = [row[:] for row in grid]
    # Isolated non-background cells whose color is not part of the stamp are
    # anchor markers; stamp the pattern horizontally with its center at each.
    anchors = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or grid[r][c] in stamp_colors:
                continue
            if all(not (0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] != bg)
                   for dr, dc in ((-1,0),(1,0),(0,-1),(0,1))):
                anchors.append((r, c))
    half = len(stamp) // 2
    for r, c in anchors:
        for i, color in enumerate(stamp):
            x = c + i - half
            if 0 <= x < w:
                out[r][x] = color
    return out
